# PY-401..PY-500: Object-Oriented Programming. This part: classes and objects (10), encapsulation (20), inheritance (20), abstraction (15).
O = "Object-Oriented Programming"
NM = ["Asha", "Ravi", "Meena", "Kiran", "Sita", "Arun", "Divya", "Naveen", "Tara", "Om"]


def cmd_block(r, n, make):
    return rows(n, *[make(r) for _ in range(n)])


# ---- 10 classes and objects ----
py(O, "Rectangle Class", "A floor-planning app models a room as a `Rectangle` class with `area()` and `perimeter()` methods. Read `n` rooms `length width` and print `area perimeter` for each.", "First line `n`, then `n` lines `length width`.", "One line per room.", "1 <= n <= 20",
   "class Rectangle:\n    def __init__(self, l, w):\n        self.l = l\n        self.w = w\n\n    def area(self):\n        return self.l * self.w\n\n    def perimeter(self):\n        return 2 * (self.l + self.w)\n\n\nn = int(input())\nfor _ in range(n):\n    r = Rectangle(*map(int, input().split()))\n    print(r.area(), r.perimeter())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.randint(1, 50)} {r.randint(1, 50)}"), edges=["1\n1 1\n"])
py(O, "Point Distance Class", "A map has a `Point` class with a method `distance_to(other)`. Read pairs of points and print the distance between them with two decimals.", "First line `n`, then `n` lines `x1 y1 x2 y2`.", "One distance per line.", "1 <= n <= 20",
   "import math\n\n\nclass Point:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n\n    def distance_to(self, o):\n        return math.hypot(self.x - o.x, self.y - o.y)\n\n\nn = int(input())\nfor _ in range(n):\n    a, b, c, d = map(int, input().split())\n    print(f\"{Point(a, b).distance_to(Point(c, d)):.2f}\")", lambda r: cmd_block(r, r.randint(1, 5), lambda r: one_line(*[r.randint(-20, 20) for _ in range(4)]).strip()), edges=["1\n0 0 0 0\n"])
py(O, "Student Report Object", "A school keeps each student as an object with `name` and a list of `marks`, and methods `average()` and `grade()` (`A` at 75 and above, `B` at 50 and above, otherwise `C`). Print `name average grade` for each student.", "First line `n`, then `n` lines `name m1 m2 ...`.", "One line per student.", "1 <= n <= 15",
   "class Student:\n    def __init__(self, name, marks):\n        self.name = name\n        self.marks = marks\n\n    def average(self):\n        return sum(self.marks) / len(self.marks)\n\n    def grade(self):\n        a = self.average()\n        return \"A\" if a >= 75 else \"B\" if a >= 50 else \"C\"\n\n\nn = int(input())\nfor _ in range(n):\n    p = input().split()\n    s = Student(p[0], list(map(int, p[1:])))\n    print(s.name, f\"{s.average():.2f}\", s.grade())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(NM)} " + " ".join(str(r.randint(20, 100)) for _ in range(r.randint(1, 4)))), edges=["1\nA 75\n"])
py(O, "Stack Class", "A browser history is a `Stack` class with `push`, `pop` and `peek`. Commands: `push x`, `pop`, `peek`. Print the popped or peeked value, or `empty` when the stack is empty.", "First line `n`, then `n` commands.", "One line for each `pop` and `peek`.", "1 <= n <= 40",
   "class Stack:\n    def __init__(self):\n        self.items = []\n\n    def push(self, x):\n        self.items.append(x)\n\n    def pop(self):\n        return self.items.pop() if self.items else \"empty\"\n\n    def peek(self):\n        return self.items[-1] if self.items else \"empty\"\n\n\ns = Stack()\nn = int(input())\nfor _ in range(n):\n    p = input().split()\n    if p[0] == \"push\":\n        s.push(p[1])\n    elif p[0] == \"pop\":\n        print(s.pop())\n    else:\n        print(s.peek())", lambda r: cmd_block(r, r.randint(4, 12), lambda r: r.choice([f"push {r.randint(1, 9)}", f"push {r.randint(1, 9)}", "pop", "peek"])), edges=["2\npop\npeek\n"])
py(O, "Queue Class for a Bank", "A bank queue is a `Queue` class with `join(name)`, `serve()` and `size()`. Commands: `join name`, `serve`, `size`. Print the name served (or `nobody`) and the size.", "First line `n`, then `n` commands.", "One line for each `serve` and `size`.", "1 <= n <= 40",
   "class Queue:\n    def __init__(self):\n        self.q = []\n\n    def join(self, n):\n        self.q.append(n)\n\n    def serve(self):\n        return self.q.pop(0) if self.q else \"nobody\"\n\n    def size(self):\n        return len(self.q)\n\n\nq = Queue()\nn = int(input())\nfor _ in range(n):\n    p = input().split()\n    if p[0] == \"join\":\n        q.join(p[1])\n    elif p[0] == \"serve\":\n        print(q.serve())\n    else:\n        print(q.size())", lambda r: cmd_block(r, r.randint(4, 12), lambda r: r.choice([f"join {r.choice(NM)}", f"join {r.choice(NM)}", "serve", "size"])), edges=["1\nserve\n"])
py(O, "Clock Time Object", "A `Time` class stores hours and minutes and has `add(minutes)` returning a new `Time`, and `show()` giving `HH:MM`. For each line `h m extra` print the time after adding `extra` minutes.", "First line `n`, then `n` lines `h m extra`.", "One `HH:MM` per line.", "0 <= h < 24, 0 <= m < 60",
   "class Time:\n    def __init__(self, h, m):\n        self.total = (h * 60 + m) % 1440\n\n    def add(self, k):\n        t = Time(0, 0)\n        t.total = (self.total + k) % 1440\n        return t\n\n    def show(self):\n        return f\"{self.total // 60:02d}:{self.total % 60:02d}\"\n\n\nn = int(input())\nfor _ in range(n):\n    h, m, k = map(int, input().split())\n    print(Time(h, m).add(k).show())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.randint(0, 23)} {r.randint(0, 59)} {r.randint(0, 2000)}"), edges=["1\n23 59 1\n"])
py(O, "Fraction Class", "A maths app has a `Fraction` class that stores a numerator and denominator in lowest terms and can `add` another fraction. For each line `a b c d` print `a/b + c/d` as a reduced fraction `p/q`.", "First line `n`, then `n` lines `a b c d` (denominators positive).", "One fraction per line.", "1 <= n <= 20",
   "from math import gcd\n\n\nclass Fraction:\n    def __init__(self, p, q):\n        g = gcd(p, q) or 1\n        self.p, self.q = p // g, q // g\n\n    def add(self, o):\n        return Fraction(self.p * o.q + o.p * self.q, self.q * o.q)\n\n    def show(self):\n        return f\"{self.p}/{self.q}\"\n\n\nn = int(input())\nfor _ in range(n):\n    a, b, c, d = map(int, input().split())\n    print(Fraction(a, b).add(Fraction(c, d)).show())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.randint(1, 9)} {r.randint(1, 9)} {r.randint(1, 9)} {r.randint(1, 9)}"), edges=["1\n1 2 1 2\n"])
py(O, "Circle Class With Class Constant", "A `Circle` class keeps `PI = 3.14159` as a class attribute and has `area()` and `circumference()`. For each radius print both with two decimals.", "First line `n`, then `n` radii.", "One line `area circumference` per radius.", "1 <= n <= 20",
   "class Circle:\n    PI = 3.14159\n\n    def __init__(self, r):\n        self.r = r\n\n    def area(self):\n        return self.PI * self.r ** 2\n\n    def circumference(self):\n        return 2 * self.PI * self.r\n\n\nn = int(input())\nfor r in map(float, input().split()):\n    c = Circle(r)\n    print(f\"{c.area():.2f} {c.circumference():.2f}\")", lambda r: (lambda n: rows(n, " ".join(str(r.randint(1, 100) / 4) for _ in range(n))))(r.randint(1, 5)), edges=["1\n1\n"])
py(O, "Cricket Player Object", "A `Player` class holds `name`, `runs` and `balls`, with `strike_rate()` (runs per 100 balls, two decimals) and a `scored(runs, balls)` method that adds to the totals. Each line `name runs balls` creates a player; print the player's strike rate after adding one more over `6` balls and `8` runs.", "First line `n`, then `n` lines `name runs balls`.", "One line `name strike_rate` per player.", "balls >= 1",
   "class Player:\n    def __init__(self, name, runs, balls):\n        self.name, self.runs, self.balls = name, runs, balls\n\n    def scored(self, runs, balls):\n        self.runs += runs\n        self.balls += balls\n\n    def strike_rate(self):\n        return self.runs * 100 / self.balls\n\n\nn = int(input())\nfor _ in range(n):\n    nm, r, b = input().split()\n    p = Player(nm, int(r), int(b))\n    p.scored(8, 6)\n    print(nm, f\"{p.strike_rate():.2f}\")", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(NM)} {r.randint(0, 120)} {r.randint(1, 90)}"), edges=["1\nA 0 1\n"])
py(O, "Playlist Object", "A `Playlist` stores song titles with `add(title)`, `remove(title)` and `show()`. Commands: `add t`, `remove t`, `show`. `show` prints the songs joined by ` | ` or `(empty)`.", "First line `n`, then `n` commands.", "One line per `show`.", "1 <= n <= 40",
   "class Playlist:\n    def __init__(self):\n        self.songs = []\n\n    def add(self, t):\n        self.songs.append(t)\n\n    def remove(self, t):\n        if t in self.songs:\n            self.songs.remove(t)\n\n    def show(self):\n        return \" | \".join(self.songs) if self.songs else \"(empty)\"\n\n\np = Playlist()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"add\":\n        p.add(c[1])\n    elif c[0] == \"remove\":\n        p.remove(c[1])\n    else:\n        print(p.show())", lambda r: cmd_block(r, r.randint(4, 12), lambda r: r.choice([f"add {r.choice(['rock', 'jazz', 'pop', 'folk'])}", f"remove {r.choice(['rock', 'jazz', 'pop', 'folk'])}", "show"])), edges=["1\nshow\n"])

# ---- 10 encapsulation: validated attribute holders ----
VALID = [
    ("Thermostat Range", "A `Thermostat` keeps its target temperature private and a setter accepts only 10 to 30 degrees", "temperature", 10, 30),
    ("Speaker Volume Control", "A `Speaker` keeps its volume private and the setter accepts only 0 to 100", "volume", 0, 100),
    ("Age Field Guard", "A `Person` keeps `age` private and the setter accepts only 0 to 120", "age", 0, 120),
    ("Speed Limiter", "A `Vehicle` keeps `speed` private and the setter accepts only 0 to 200", "speed", 0, 200),
    ("Battery Level Guard", "A `Phone` keeps `battery` private and the setter accepts only 0 to 100", "battery", 0, 100),
    ("Discount Percent Guard", "A `Product` keeps `discount` private and the setter accepts only 0 to 90", "discount", 0, 90),
    ("Rating Guard", "A `Review` keeps `stars` private and the setter accepts only 1 to 5", "stars", 1, 5),
    ("Seat Quantity Guard", "A `Booking` keeps `seats` private and the setter accepts only 1 to 10", "seats", 1, 10),
    ("Weight Limit Guard", "A `Parcel` keeps `kg` private and the setter accepts only 1 to 500", "kg", 1, 500),
    ("Exam Marks Guard", "A `Paper` keeps `marks` private and the setter accepts only 0 to 100", "marks", 0, 100),
]
for title, scene, attr, lo, hi in VALID:
    cls = scene.split("`")[1]
    py(O, title, f"{scene}. Process `n` commands `set value`; print `OK` and store it when valid, otherwise print `Invalid`. A final `get` command prints the stored value (start value {lo}).", "First line `n`, then `n` commands `set v` or `get`.", "One line per command.", "1 <= n <= 30",
       f"class {cls}:\n    def __init__(self):\n        self.__{attr} = {lo}\n\n    @property\n    def {attr}(self):\n        return self.__{attr}\n\n    @{attr}.setter\n    def {attr}(self, v):\n        if {lo} <= v <= {hi}:\n            self.__{attr} = v\n            return\n        raise ValueError\n\n\nobj = {cls}()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"get\":\n        print(obj.{attr})\n    else:\n        try:\n            obj.{attr} = int(c[1])\n            print(\"OK\")\n        except ValueError:\n            print(\"Invalid\")",
       lambda r, lo=lo, hi=hi: cmd_block(r, r.randint(3, 9), lambda r: r.choice([f"set {r.randint(lo - 5, hi + 5)}", f"set {r.randint(lo, hi)}", "get"])), edges=["1\nget\n"])

# ---- 10 encapsulation: bespoke classes ----
py(O, "Private Bank Balance", "A `BankAccount` hides its balance. `deposit(x)` adds money, `withdraw(x)` removes it only if the balance is enough (else the account says `Insufficient funds`), and `balance()` reports it. Run `n` commands and print the result of each `withdraw` (`OK` or the message) and `balance`.", "First line `start n`, then `n` commands `deposit x`, `withdraw x` or `balance`.", "One line per `withdraw` and `balance`.", "1 <= n <= 30",
   "class BankAccount:\n    def __init__(self, start):\n        self.__bal = start\n\n    def deposit(self, x):\n        self.__bal += x\n\n    def withdraw(self, x):\n        if x > self.__bal:\n            return \"Insufficient funds\"\n        self.__bal -= x\n        return \"OK\"\n\n    def balance(self):\n        return self.__bal\n\n\nstart, n = map(int, input().split())\na = BankAccount(start)\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"deposit\":\n        a.deposit(int(c[1]))\n    elif c[0] == \"withdraw\":\n        print(a.withdraw(int(c[1])))\n    else:\n        print(a.balance())", lambda r: (lambda n: rows(f"{r.randint(0, 500)} {n}", *[r.choice([f"deposit {r.randint(1, 300)}", f"withdraw {r.randint(1, 400)}", "balance"]) for _ in range(n)]))(r.randint(3, 9)), edges=["0 1\nbalance\n"])
py(O, "PIN Locked Locker", "A `Locker` stores a secret PIN privately. `open(pin)` returns `Open` for the right PIN, `Wrong PIN` otherwise, and after three wrong attempts in a row returns `Locked` for every later attempt (even a correct one). Process `n` attempts.", "First line `pin n`, then `n` attempts.", "One line per attempt.", "1 <= n <= 20",
   "class Locker:\n    def __init__(self, pin):\n        self.__pin = pin\n        self.__bad = 0\n\n    def open(self, pin):\n        if self.__bad >= 3:\n            return \"Locked\"\n        if pin == self.__pin:\n            self.__bad = 0\n            return \"Open\"\n        self.__bad += 1\n        return \"Wrong PIN\"\n\n\npin, n = input().split()\nl = Locker(pin)\nfor _ in range(int(n)):\n    print(l.open(input().strip()))", lambda r: (lambda n: rows(f"1234 {n}", *[r.choice(["1234", "0000", "1111", "4321"]) for _ in range(n)]))(r.randint(3, 9)), edges=["1234 1\n1234\n"])
py(O, "Library Member Limit", "A `Member` can borrow at most 3 books. `borrow(book)` adds a book (or says `Limit reached`) and `give_back(book)` removes it (or says `Not borrowed`). Print the response of each command (`OK` for success).", "First line `n`, then `n` commands `borrow b` or `return b`.", "One line per command.", "1 <= n <= 30",
   "class Member:\n    def __init__(self):\n        self._books = []\n\n    def borrow(self, b):\n        if len(self._books) >= 3:\n            return \"Limit reached\"\n        self._books.append(b)\n        return \"OK\"\n\n    def give_back(self, b):\n        if b not in self._books:\n            return \"Not borrowed\"\n        self._books.remove(b)\n        return \"OK\"\n\n\nm = Member()\nn = int(input())\nfor _ in range(n):\n    c, b = input().split()\n    print(m.borrow(b) if c == \"borrow\" else m.give_back(b))", lambda r: cmd_block(r, r.randint(4, 10), lambda r: f"{r.choice(['borrow', 'borrow', 'return'])} {r.choice(['dune', 'emma', 'hamlet', 'ulysses', 'iliad'])}"), edges=["1\nreturn x\n"])
py(O, "Read-Only Order Total", "An `Order` keeps item prices in a private list. `add(price)` appends, and the read-only property `total` returns the sum. Trying `total = 0` raises an error: print `read-only` when that happens. Commands: `add x`, `total`, `set`.", "First line `n`, then `n` commands.", "One line per `total` or `set`.", "1 <= n <= 30",
   "class Order:\n    def __init__(self):\n        self.__prices = []\n\n    def add(self, p):\n        self.__prices.append(p)\n\n    @property\n    def total(self):\n        return sum(self.__prices)\n\n\no = Order()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"add\":\n        o.add(int(c[1]))\n    elif c[0] == \"total\":\n        print(o.total)\n    else:\n        try:\n            o.total = 0\n        except AttributeError:\n            print(\"read-only\")", lambda r: cmd_block(r, r.randint(4, 10), lambda r: r.choice([f"add {r.randint(5, 99)}", f"add {r.randint(5, 99)}", "total", "set"])), edges=["1\nset\n"])
py(O, "Celsius Property Conversion", "A `Temperature` class stores Celsius privately and exposes a `fahrenheit` property (read) and a setter for it. Commands: `c x` sets Celsius, `f x` sets Fahrenheit, `show` prints `celsius fahrenheit` with one decimal each.", "First line `n`, then `n` commands.", "One line per `show`.", "1 <= n <= 30",
   "class Temperature:\n    def __init__(self):\n        self.__c = 0.0\n\n    @property\n    def celsius(self):\n        return self.__c\n\n    @celsius.setter\n    def celsius(self, v):\n        self.__c = v\n\n    @property\n    def fahrenheit(self):\n        return self.__c * 9 / 5 + 32\n\n    @fahrenheit.setter\n    def fahrenheit(self, v):\n        self.__c = (v - 32) * 5 / 9\n\n\nt = Temperature()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"c\":\n        t.celsius = float(c[1])\n    elif c[0] == \"f\":\n        t.fahrenheit = float(c[1])\n    else:\n        print(f\"{t.celsius:.1f} {t.fahrenheit:.1f}\")", lambda r: cmd_block(r, r.randint(3, 8), lambda r: r.choice([f"c {r.randint(-30, 50)}", f"f {r.randint(-20, 120)}", "show"])), edges=["1\nshow\n"])
py(O, "Stock Keeper With Floor", "A `Shelf` keeps its quantity private. `add(x)` increases it, `remove(x)` decreases it but never below zero (it returns the amount actually removed), and `qty()` reports it. Print the removed amount for `remove` and the quantity for `qty`.", "First line `n`, then `n` commands `add x`, `remove x` or `qty`.", "One line per `remove` and `qty`.", "1 <= n <= 30",
   "class Shelf:\n    def __init__(self):\n        self.__q = 0\n\n    def add(self, x):\n        self.__q += x\n\n    def remove(self, x):\n        taken = min(x, self.__q)\n        self.__q -= taken\n        return taken\n\n    def qty(self):\n        return self.__q\n\n\ns = Shelf()\nn = int(input())\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"add\":\n        s.add(int(c[1]))\n    elif c[0] == \"remove\":\n        print(s.remove(int(c[1])))\n    else:\n        print(s.qty())", lambda r: cmd_block(r, r.randint(4, 10), lambda r: r.choice([f"add {r.randint(1, 30)}", f"remove {r.randint(1, 40)}", "qty"])), edges=["1\nqty\n"])
py(O, "Password Strength Property", "A `Password` class stores the text privately and exposes a read-only `strength`: `Strong` if it has at least 8 characters, a digit and an upper-case letter, `Medium` if it has at least 6 characters, otherwise `Weak`. Print the strength for each password.", "First line `n`, then `n` passwords.", "One strength per line.", "1 <= n <= 20",
   "class Password:\n    def __init__(self, text):\n        self.__text = text\n\n    @property\n    def strength(self):\n        t = self.__text\n        if len(t) >= 8 and any(c.isdigit() for c in t) and any(c.isupper() for c in t):\n            return \"Strong\"\n        return \"Medium\" if len(t) >= 6 else \"Weak\"\n\n\nn = int(input())\nfor _ in range(n):\n    print(Password(input().strip()).strength)", lambda r: cmd_block(r, r.randint(2, 6), lambda r: r.choice(["abc", "abcdef", "Passw0rdX", "longpassword", "A1", "Secret123", "hello1"])), edges=["1\nabc\n"])
py(O, "Protected Counter", "A `Counter` stores its count in a protected attribute `_n`. `tick()` adds 1, `reset()` sets 0 and `value()` reports it. Print `value` after every command in `tick`, `reset`, `value`.", "First line `n`, then `n` commands.", "One line per `value`.", "1 <= n <= 40",
   "class Counter:\n    def __init__(self):\n        self._n = 0\n\n    def tick(self):\n        self._n += 1\n\n    def reset(self):\n        self._n = 0\n\n    def value(self):\n        return self._n\n\n\nc = Counter()\nn = int(input())\nfor _ in range(n):\n    cmd = input().strip()\n    if cmd == \"tick\":\n        c.tick()\n    elif cmd == \"reset\":\n        c.reset()\n    else:\n        print(c.value())", lambda r: cmd_block(r, r.randint(4, 12), lambda r: r.choice(["tick", "tick", "reset", "value"])), edges=["1\nvalue\n"])
py(O, "Name Mangling Check", "A `Secret` class has a private attribute `__code`. Read the attribute name from the input; print `visible` if `hasattr(obj, name)` is true, else `hidden`. Test the names `__code`, `_Secret__code` and `code`.", "First line `n`, then `n` attribute names.", "One verdict per name.", "1 <= n <= 6",
   "class Secret:\n    def __init__(self):\n        self.__code = 42\n\n\ns = Secret()\nn = int(input())\nfor _ in range(n):\n    print(\"visible\" if hasattr(s, input().strip()) else \"hidden\")", lambda r: cmd_block(r, r.randint(2, 5), lambda r: r.choice(["__code", "_Secret__code", "code"])), edges=["1\n__code\n"])
py(O, "Wallet With Daily Limit", "A `Wallet` allows spending at most `limit` per day. `spend(x)` returns `Spent` when the total for the day stays within the limit, else `Limit exceeded`; `new_day()` clears the day's total. Process commands.", "First line `limit n`, then `n` commands `spend x` or `newday`.", "One line per `spend`.", "1 <= n <= 30",
   "class Wallet:\n    def __init__(self, limit):\n        self.__limit = limit\n        self.__today = 0\n\n    def spend(self, x):\n        if self.__today + x > self.__limit:\n            return \"Limit exceeded\"\n        self.__today += x\n        return \"Spent\"\n\n    def new_day(self):\n        self.__today = 0\n\n\nlimit, n = map(int, input().split())\nw = Wallet(limit)\nfor _ in range(n):\n    c = input().split()\n    if c[0] == \"spend\":\n        print(w.spend(int(c[1])))\n    else:\n        w.new_day()", lambda r: (lambda n: rows(f"{r.randint(100, 500)} {n}", *[r.choice([f"spend {r.randint(10, 300)}", f"spend {r.randint(10, 300)}", "newday"]) for _ in range(n)]))(r.randint(3, 9)), edges=["10 1\nspend 11\n"])

# ---- 8 inheritance: a base class and three subclasses overriding one method ----
HIER = [
    ("Staff Pay by Role", "A company has an `Employee` base class with `pay()` returning the base salary. `Manager` pays base + 5000, `Engineer` pays base + a tenth of the base (rounded down) and `Intern` pays half the base (rounded down). Each line gives `role name base`; print `name pay`.", "Employee", [("manager", "Manager", "self.base + 5000"), ("engineer", "Engineer", "self.base + self.base // 10"), ("intern", "Intern", "self.base // 2")], "base", (10000, 90000)),
    ("Toll by Vehicle", "A toll plaza has a `Vehicle` class with `toll()` returning the distance in km. `Car` pays double, `Truck` pays 5 per km plus 50 and `Bus` pays 3 per km plus 20. Each line `kind name km`; print `name toll`.", "Vehicle", [("car", "Car", "2 * self.base"), ("truck", "Truck", "5 * self.base + 50"), ("bus", "Bus", "3 * self.base + 20")], "km", (1, 400)),
    ("Shape Surface", "A `Shape` base class returns its size as the `area()`. `Square` returns side squared, `Cube` returns its surface area `6 * side^2` and `Plate` returns twice the square of the side. Each line `kind name side`; print `name area`.", "Shape", [("square", "Square", "self.base ** 2"), ("cube", "Cube", "6 * self.base ** 2"), ("plate", "Plate", "2 * self.base ** 2")], "side", (1, 60)),
    ("Courier Charges", "A `Parcel` class has `charge()` returning the weight. `Standard` charges 10 per kg, `Express` 25 per kg plus 30 and `Fragile` 15 per kg plus 100. Each line `kind name kg`; print `name charge`.", "Parcel", [("standard", "Standard", "10 * self.base"), ("express", "Express", "25 * self.base + 30"), ("fragile", "Fragile", "15 * self.base + 100")], "kg", (1, 50)),
    ("Account Yearly Interest", "An `Account` class has `interest()`. `Savings` gives 4% of the balance (rounded down), `Current` gives nothing and `Fixed` gives 7% (rounded down). Each line `kind name balance`; print `name interest`.", "Account", [("savings", "Savings", "self.base * 4 // 100"), ("current", "Current", "0"), ("fixed", "Fixed", "self.base * 7 // 100")], "balance", (1000, 90000)),
    ("Ticket Fare by Passenger", "A `Ticket` class has `fare()` returning the base fare. `Child` pays half (rounded down), `Adult` pays the full fare and `Senior` pays 60% (rounded down). Each line `kind name fare`; print `name fare`.", "Ticket", [("child", "Child", "self.base // 2"), ("adult", "Adult", "self.base"), ("senior", "Senior", "self.base * 6 // 10")], "fare", (20, 900)),
    ("Delivery Minutes by Mode", "A `Mode` class has `minutes()`. `Bike` takes 3 minutes per km, `Car` 2 minutes per km and `Drone` 1 minute per km. Each line `kind name km`; print `name minutes`.", "Mode", [("bike", "Bike", "3 * self.base"), ("car", "Car", "2 * self.base"), ("drone", "Drone", "self.base")], "km", (1, 100)),
    ("Hotel Bill by Room", "A `Room` class has `bill()` for the number of nights. `Standard` costs 1500 per night, `Deluxe` 2500 per night plus 300 and `Suite` 4000 per night plus 500. Each line `kind name nights`; print `name bill`.", "Room", [("standard", "Standard", "1500 * self.base"), ("deluxe", "Deluxe", "2500 * self.base + 300"), ("suite", "Suite", "4000 * self.base + 500")], "nights", (1, 14)),
]
for title, scene, base, kinds, unit, (lo, hi) in HIER:
    method = scene.split("`")[3].split("(")[0]
    subs = "\n\n\n".join(f"class {cn}({base}):\n    def {method}(self):\n        return {expr}" for _, cn, expr in kinds)
    table = ", ".join(f'"{k}": {cn}' for k, cn, _ in kinds)
    sol = f"class {base}:\n    def __init__(self, name, base):\n        self.name = name\n        self.base = base\n\n    def {method}(self):\n        return self.base\n\n\n{subs}\n\n\ntable = {{{table}}}\nn = int(input())\nfor _ in range(n):\n    kind, name, x = input().split()\n    print(name, table[kind](name, int(x)).{method}())"
    ks = [k for k, _, _ in kinds]
    py(O, title, scene, f"First line `n`, then `n` lines `kind name {unit}`.", "One line per object.", f"1 <= n <= 20, {lo} <= {unit} <= {hi}", sol,
       lambda r, ks=ks, lo=lo, hi=hi: cmd_block(r, r.randint(2, 6), lambda r: f"{r.choice(ks)} {r.choice(NM)} {r.randint(lo, hi)}"), edges=[f"1\n{ks[0]} A {lo}\n"])

# ---- 12 inheritance: bespoke chains ----
py(O, "Super Init Chain", "A `Person` stores a name; `Student` extends it with a roll number using `super().__init__`, and `Prefect` extends `Student` with a duty. Each line `name roll duty`; print `Prefect <name> (<roll>) on <duty>`.", "First line `n`, then `n` lines.", "One line per prefect.", "1 <= n <= 20",
   "class Person:\n    def __init__(self, name):\n        self.name = name\n\n\nclass Student(Person):\n    def __init__(self, name, roll):\n        super().__init__(name)\n        self.roll = roll\n\n\nclass Prefect(Student):\n    def __init__(self, name, roll, duty):\n        super().__init__(name, roll)\n        self.duty = duty\n\n    def describe(self):\n        return f\"Prefect {self.name} ({self.roll}) on {self.duty}\"\n\n\nn = int(input())\nfor _ in range(n):\n    a, b, c = input().split()\n    print(Prefect(a, b, c).describe())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(NM)} {r.randint(1, 99)} {r.choice(['gate', 'library', 'lab'])}"), edges=["1\nA 1 gate\n"])
py(O, "Multilevel Pay Grade", "`Worker` pays `rate * hours`; `Supervisor` extends `Worker` and adds a fixed allowance of 500; `Foreman` extends `Supervisor` and adds 10% of the allowed total (rounded down). Each line `rate hours`; print the pay of a `Foreman`.", "First line `n`, then `n` lines `rate hours`.", "One pay per line.", "1 <= n <= 20",
   "class Worker:\n    def __init__(self, rate, hours):\n        self.rate, self.hours = rate, hours\n\n    def pay(self):\n        return self.rate * self.hours\n\n\nclass Supervisor(Worker):\n    def pay(self):\n        return super().pay() + 500\n\n\nclass Foreman(Supervisor):\n    def pay(self):\n        t = super().pay()\n        return t + t // 10\n\n\nn = int(input())\nfor _ in range(n):\n    a, b = map(int, input().split())\n    print(Foreman(a, b).pay())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.randint(50, 300)} {r.randint(1, 60)}"), edges=["1\n1 1\n"])
py(O, "Method Resolution Order", "Class `A` has `hello()` returning `A`; `B(A)` returns `B` + `super().hello()`; `C(A)` returns `C` + `super().hello()`; `D(B, C)` returns `D` + `super().hello()`. Print `D().hello()`, then the class names of `D`'s MRO separated by spaces.", "No input.", "Two lines.", "None.",
   "class A:\n    def hello(self):\n        return \"A\"\n\n\nclass B(A):\n    def hello(self):\n        return \"B\" + super().hello()\n\n\nclass C(A):\n    def hello(self):\n        return \"C\" + super().hello()\n\n\nclass D(B, C):\n    def hello(self):\n        return \"D\" + super().hello()\n\n\nprint(D().hello())\nprint(*(c.__name__ for c in D.__mro__))", lambda r: "\n", n=1)
py(O, "isinstance and issubclass", "With classes `Animal`, `Dog(Animal)` and `Puppy(Dog)`, read pairs `object_class base_class` and print `True` or `False` for whether an instance of the first is an instance of the second.", "First line `n`, then `n` lines of class names.", "One line per pair.", "Class names are `Animal`, `Dog` or `Puppy`.",
   "class Animal:\n    pass\n\n\nclass Dog(Animal):\n    pass\n\n\nclass Puppy(Dog):\n    pass\n\n\nk = {\"Animal\": Animal, \"Dog\": Dog, \"Puppy\": Puppy}\nn = int(input())\nfor _ in range(n):\n    a, b = input().split()\n    print(isinstance(k[a](), k[b]))", lambda r: cmd_block(r, r.randint(2, 6), lambda r: f"{r.choice(['Animal', 'Dog', 'Puppy'])} {r.choice(['Animal', 'Dog', 'Puppy'])}"), edges=["1\nPuppy Animal\n"])
py(O, "Multiple Inheritance Skills", "`Swimmer` has `skills()` returning `swim`; `Runner` returns `run`; `Triathlete(Swimmer, Runner)` returns the skills of both parents joined by `+`, each from its own parent via `super`-free calls. Each input line is a name; print `<name>: <skills>`.", "First line `n`, then `n` names.", "One line per athlete.", "1 <= n <= 20",
   "class Swimmer:\n    def skills(self):\n        return \"swim\"\n\n\nclass Runner:\n    def skills(self):\n        return \"run\"\n\n\nclass Triathlete(Swimmer, Runner):\n    def skills(self):\n        return Swimmer.skills(self) + \"+\" + Runner.skills(self)\n\n\nn = int(input())\nfor _ in range(n):\n    print(f\"{input().strip()}: {Triathlete().skills()}\")", lambda r: cmd_block(r, r.randint(1, 4), lambda r: r.choice(NM)), edges=["1\nA\n"])
py(O, "Override and Extend Greeting", "`Greeter.greet(name)` returns `Hello, <name>`. `LoudGreeter` overrides it to call the parent's version and add `!!!`. `FormalGreeter` returns `Dear <name>`. Each line `kind name`; print the greeting.", "First line `n`, then `n` lines `kind name` where kind is `plain`, `loud` or `formal`.", "One greeting per line.", "1 <= n <= 20",
   "class Greeter:\n    def greet(self, name):\n        return f\"Hello, {name}\"\n\n\nclass LoudGreeter(Greeter):\n    def greet(self, name):\n        return super().greet(name) + \"!!!\"\n\n\nclass FormalGreeter(Greeter):\n    def greet(self, name):\n        return f\"Dear {name}\"\n\n\nk = {\"plain\": Greeter, \"loud\": LoudGreeter, \"formal\": FormalGreeter}\nn = int(input())\nfor _ in range(n):\n    a, b = input().split()\n    print(k[a]().greet(b))", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(['plain', 'loud', 'formal'])} {r.choice(NM)}"), edges=["1\nloud A\n"])
py(O, "Library Item Hierarchy", "`Item` stores a title and has `late_fee(days)` returning `days` rupees. `Book` charges 2 per day and `DVD` charges 5 per day plus a flat 10 when late by more than 7 days. Each line `kind title days`; print `title fee`.", "First line `n`, then `n` lines.", "One line per item.", "1 <= n <= 20, 0 <= days <= 60",
   "class Item:\n    def __init__(self, title):\n        self.title = title\n\n    def late_fee(self, d):\n        return d\n\n\nclass Book(Item):\n    def late_fee(self, d):\n        return 2 * d\n\n\nclass DVD(Item):\n    def late_fee(self, d):\n        return 5 * d + (10 if d > 7 else 0)\n\n\nk = {\"item\": Item, \"book\": Book, \"dvd\": DVD}\nn = int(input())\nfor _ in range(n):\n    a, t, d = input().split()\n    print(t, k[a](t).late_fee(int(d)))", lambda r: cmd_block(r, r.randint(1, 5), lambda r: f"{r.choice(['item', 'book', 'dvd'])} {r.choice(['dune', 'emma', 'jaws', 'up'])} {r.randint(0, 20)}"), edges=["1\ndvd x 8\n"])
py(O, "Class Hierarchy Depth", "In the chain `Base`, `Mid(Base)`, `Leaf(Mid)` each class has `level()`: Base returns 1, Mid returns the parent's level plus 1 and Leaf returns the parent's level plus 1. Read class names and print each class's level.", "First line `n`, then `n` class names.", "One level per line.", "Names are `Base`, `Mid` or `Leaf`.",
   "class Base:\n    def level(self):\n        return 1\n\n\nclass Mid(Base):\n    def level(self):\n        return super().level() + 1\n\n\nclass Leaf(Mid):\n    def level(self):\n        return super().level() + 1\n\n\nk = {\"Base\": Base, \"Mid\": Mid, \"Leaf\": Leaf}\nn = int(input())\nfor _ in range(n):\n    print(k[input().strip()]().level())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: r.choice(["Base", "Mid", "Leaf"])), edges=["1\nLeaf\n"])
py(O, "Child Class Adds Attributes", "`Vehicle(name, wheels)` has `info()` returning `<name> has <wheels> wheels`. `ElectricVehicle` extends it with a `range_km` and its `info()` appends `, range <k> km`. Each line `kind name wheels [range]`; print `info()`.", "First line `n`, then `n` lines; `electric` lines have a fourth value.", "One line per vehicle.", "1 <= n <= 20",
   "class Vehicle:\n    def __init__(self, name, wheels):\n        self.name, self.wheels = name, wheels\n\n    def info(self):\n        return f\"{self.name} has {self.wheels} wheels\"\n\n\nclass ElectricVehicle(Vehicle):\n    def __init__(self, name, wheels, rng):\n        super().__init__(name, wheels)\n        self.rng = rng\n\n    def info(self):\n        return super().info() + f\", range {self.rng} km\"\n\n\nn = int(input())\nfor _ in range(n):\n    p = input().split()\n    if p[0] == \"electric\":\n        print(ElectricVehicle(p[1], int(p[2]), int(p[3])).info())\n    else:\n        print(Vehicle(p[1], int(p[2])).info())", lambda r: cmd_block(r, r.randint(1, 5), lambda r: r.choice([f"plain {r.choice(['bike', 'car', 'cart'])} {r.choice([2, 3, 4])}", f"electric {r.choice(['zap', 'volt'])} {r.choice([2, 4])} {r.randint(50, 400)}"])), edges=["1\nplain a 2\n"])
py(O, "Shared Parent State", "`Counter` has a class attribute `total` counting every object created by itself or by its subclass `SubCounter`. Create `a` Counters and `b` SubCounters and print `total` followed by `SubCounter.total is Counter.total`.", "One line `a b`.", "Two lines.", "0 <= a, b <= 50",
   "class Counter:\n    total = 0\n\n    def __init__(self):\n        Counter.total += 1\n\n\nclass SubCounter(Counter):\n    pass\n\n\na, b = map(int, input().split())\nfor _ in range(a):\n    Counter()\nfor _ in range(b):\n    SubCounter()\nprint(Counter.total)\nprint(SubCounter.total is Counter.total)", lambda r: one_line(r.randint(0, 9), r.randint(0, 9)), edges=["0 0\n"])
py(O, "Parent Method Call Order", "`Base.setup()` prints `base`; `Child(Base).setup()` prints `child` and then calls the parent's `setup`; `GrandChild(Child).setup()` prints `grandchild` and then calls its parent. Read a class name and call `setup()` on a new object.", "One class name: `Base`, `Child` or `GrandChild`.", "The printed lines.", "One of the three names.",
   "class Base:\n    def setup(self):\n        print(\"base\")\n\n\nclass Child(Base):\n    def setup(self):\n        print(\"child\")\n        super().setup()\n\n\nclass GrandChild(Child):\n    def setup(self):\n        print(\"grandchild\")\n        super().setup()\n\n\n{\"Base\": Base, \"Child\": Child, \"GrandChild\": GrandChild}[input().strip()]().setup()", lambda r: r.choice(["Base", "Child", "GrandChild"]) + "\n", edges=["Base\n", "Child\n", "GrandChild\n"])
py(O, "Override Equality in Subclass", "`Point(x, y)` compares equal to another `Point` with the same coordinates. `Point3D(x, y, z)` extends it and also needs `z` to match. For each line `kind x y [z] kind x y [z]` print whether the two objects are equal (`True` or `False`).", "First line `n`, then `n` lines of two shapes.", "One `True` or `False` per line.", "1 <= n <= 20",
   "class Point:\n    def __init__(self, x, y):\n        self.x, self.y = x, y\n\n    def __eq__(self, o):\n        return type(self) is type(o) and (self.x, self.y) == (o.x, o.y)\n\n\nclass Point3D(Point):\n    def __init__(self, x, y, z):\n        super().__init__(x, y)\n        self.z = z\n\n    def __eq__(self, o):\n        return super().__eq__(o) and self.z == o.z\n\n\ndef read(t):\n    return Point3D(*map(int, t[1:4])) if t[0] == \"p3\" else Point(*map(int, t[1:3]))\n\n\nn = int(input())\nfor _ in range(n):\n    t = input().split()\n    k = 4 if t[0] == \"p3\" else 3\n    print(read(t[:k]) == read(t[k:]) if t[k:] else False)", lambda r: cmd_block(r, r.randint(1, 5), lambda r: (lambda a, b: f"p2 {a[0]} {a[1]} p2 {b[0]} {b[1]}" if r.random() < .5 else f"p3 {a[0]} {a[1]} 1 p3 {b[0]} {b[1]} {r.choice([1, 2])}")((r.randint(0, 2), r.randint(0, 2)), (r.randint(0, 2), r.randint(0, 2)))), edges=["1\np2 1 1 p2 1 1\n"])

# ---- 8 abstraction (abc): an abstract base class and three concrete classes ----
ABST = [
    ("Payment Gateway Fees", "An abstract `Gateway` class declares `fee(amount)` and has a concrete `receipt(amount)` returning `<name>: <fee>`. `Card` charges 2% (rounded down), `UPI` charges nothing and `NetBanking` charges a flat 15. Each line `kind amount`; print the receipt.", "Gateway", [("card", "Card", "Card", "amount * 2 // 100"), ("upi", "UPI", "UPI", "0"), ("netbanking", "NetBanking", "NetBanking", "15")], "amount", (100, 50000)),
    ("Notification Channels Cost", "An abstract `Channel` declares `cost(count)`; its concrete `quote(count)` returns `<name>: <cost>`. `SMS` costs 1 per message, `Email` costs 1 per 4 messages (rounded up) and `Push` is free. Each line `kind count`; print the quote.", "Channel", [("sms", "SMS", "SMS", "count"), ("email", "Email", "Email", "(count + 3) // 4"), ("push", "Push", "Push", "0")], "count", (1, 500)),
    ("Exporter Size Estimates", "An abstract `Exporter` declares `size(rows)`; the concrete `label(rows)` returns `<name>: <size> KB`. `CSV` needs 1 KB per 10 rows (rounded up), `JSON` needs 3 KB per 10 rows (rounded up) and `PDF` needs 5 KB plus 2 KB per 10 rows (rounded up). Each line `kind rows`; print the label.", "Exporter", [("csv", "CSV", "CSV", "(rows + 9) // 10"), ("json", "JSON", "JSON", "3 * ((rows + 9) // 10)"), ("pdf", "PDF", "PDF", "5 + 2 * ((rows + 9) // 10)")], "rows", (1, 900)),
    ("Printer Job Costs", "An abstract `Printer` declares `cost(pages)`; the concrete `bill(pages)` returns `<name>: <cost>`. `Laser` charges 3 per page, `Inkjet` 5 per page and `ThreeD` a flat 100 plus 20 per page. Each line `kind pages`; print the bill.", "Printer", [("laser", "Laser", "Laser", "3 * pages"), ("inkjet", "Inkjet", "Inkjet", "5 * pages"), ("threed", "ThreeD", "ThreeD", "100 + 20 * pages")], "pages", (1, 200)),
    ("Loyalty Tier Points", "An abstract `Tier` declares `points(spend)`; the concrete `summary(spend)` returns `<name>: <points>`. `Silver` gives 1 point per 100 spent, `Gold` gives 2 per 100 and `Platinum` gives 3 per 100 plus a 50 bonus. Each line `kind spend`; print the summary.", "Tier", [("silver", "Silver", "Silver", "spend // 100"), ("gold", "Gold", "Gold", "2 * (spend // 100)"), ("platinum", "Platinum", "Platinum", "3 * (spend // 100) + 50")], "spend", (100, 20000)),
    ("Sensor Scale Readings", "An abstract `Sensor` declares `convert(raw)`; the concrete `report(raw)` returns `<name>: <value>`. `Pressure` divides the raw reading by 10 (rounded down), `Light` doubles it and `Sound` subtracts 20 but never goes below 0. Each line `kind raw`; print the report.", "Sensor", [("pressure", "Pressure", "Pressure", "raw // 10"), ("light", "Light", "Light", "2 * raw"), ("sound", "Sound", "Sound", "max(0, raw - 20)")], "raw", (0, 1000)),
    ("Compression Savings", "An abstract `Codec` declares `compressed(size)`; the concrete `savings(size)` returns `<name>: <size - compressed>`. `Zip` shrinks to 60% (rounded down), `Gzip` to 50% and `Raw` stays the same. Each line `kind size`; print the savings.", "Codec", [("zip", "Zip", "Zip", "size * 6 // 10"), ("gzip", "Gzip", "Gzip", "size // 2"), ("raw", "Raw", "Raw", "size")], "size", (10, 5000)),
    ("Tax by Category", "An abstract `Category` declares `tax(price)`; the concrete `line(price)` returns `<name>: <tax>`. `Food` is taxed at 5%, `Electronics` at 18% and `Luxury` at 28% (all rounded down). Each line `kind price`; print the tax line.", "Category", [("food", "Food", "Food", "price * 5 // 100"), ("electronics", "Electronics", "Electronics", "price * 18 // 100"), ("luxury", "Luxury", "Luxury", "price * 28 // 100")], "price", (100, 90000)),
]
for title, scene, base, kinds, unit, (lo, hi) in ABST:
    method = scene.split("`")[3].split("(")[0]
    concrete = scene.split("concrete `")[1].split("(")[0]
    subs = "\n\n\n".join(f"class {cn}({base}):\n    def {method}(self, {unit}):\n        return {expr}" for _, _, cn, expr in kinds)
    if method == "compressed":
        body = "        return f\"{type(self).__name__}: {size - self.compressed(size)}\""
    else:
        body = f"        return f\"{{type(self).__name__}}: {{self.{method}({unit})}}" + (" KB" if "KB" in scene else "") + "\""
    tbl = ", ".join('"%s": %s' % (k, cn) for k, _, cn, _ in kinds)
    sol = f"from abc import ABC, abstractmethod\n\n\nclass {base}(ABC):\n    @abstractmethod\n    def {method}(self, {unit}):\n        ...\n\n    def {concrete}(self, {unit}):\n{body}\n\n\n{subs}\n\n\ntable = {{{tbl}}}\nn = int(input())\nfor _ in range(n):\n    kind, x = input().split()\n    print(table[kind]().{concrete}(int(x)))"
    ks = [k for k, _, _, _ in kinds]
    py(O, title, scene, f"First line `n`, then `n` lines `kind {unit}`.", "One line per request.", f"1 <= n <= 20, {lo} <= {unit} <= {hi}", sol,
       lambda r, ks=ks, lo=lo, hi=hi: cmd_block(r, r.randint(2, 6), lambda r: f"{r.choice(ks)} {r.randint(lo, hi)}"), edges=[f"1\n{ks[0]} {lo}\n"])
